import{NODE_WIDTH as W,NODE_HEIGHT as H,clampNodeW,clampNodeH}from'./mopix-node-graph.js';
const nodeW=n=>clampNodeW(n.w),nodeH=n=>clampNodeH(n.h);
const MIN_ZOOM=.12,MAX_ZOOM=2.5;
export function zoomAt(view,nextZoom,x,y){const z=Math.max(MIN_ZOOM,Math.min(MAX_ZOOM,nextZoom));return{x:x-(x-view.x)*z/view.z,y:y-(y-view.y)*z/view.z,z}}
export function wheelZoom(view,event,rect){const units=event.deltaMode===1?16:event.deltaMode===2?rect.height:1,delta=Math.max(-180,Math.min(180,event.deltaY*units));return zoomAt(view,view.z*Math.exp(-delta*.0035),event.clientX-rect.left,event.clientY-rect.top)}
export function groupBounds(graph,group){const members=graph.nodes.filter(n=>group.nodeIds.includes(n.id));if(!members.length)return null;const x=Math.min(...members.map(n=>n.x))-20,y=Math.min(...members.map(n=>n.y))-58;return{x,y,width:group.collapsed?324:Math.max(...members.map(n=>n.x+nodeW(n)))-x+20,height:group.collapsed?150:Math.max(...members.map(n=>n.y+nodeH(n)))-y+20}}
export function visibleBounds(graph,groupId){const groups=(graph.groups||[]).filter(g=>g.nodeIds.some(id=>graph.nodes.some(n=>n.id===id))),hidden=new Set(groups.filter(g=>g.collapsed).flatMap(g=>g.nodeIds));let items=groupId?groups.filter(g=>g.id===groupId).map(g=>groupBounds(graph,g)):groups.map(g=>groupBounds(graph,g));if(!groupId)items.push(...graph.nodes.filter(n=>!hidden.has(n.id)).map(n=>({x:n.x,y:n.y,width:nodeW(n),height:nodeH(n)})));items=items.filter(Boolean);if(!items.length)return null;const x=Math.min(...items.map(i=>i.x)),y=Math.min(...items.map(i=>i.y));return{x,y,width:Math.max(...items.map(i=>i.x+i.width))-x,height:Math.max(...items.map(i=>i.y+i.height))-y}}
export function fitCanvas(graph,width,height,groupId){const b=visibleBounds(graph,groupId);if(!b)return{x:60,y:100,z:1};const top=84,bottom=64,side=32,availableW=Math.max(1,width-side*2),availableH=Math.max(1,height-top-bottom),z=Math.max(MIN_ZOOM,Math.min(1,availableW/(b.width+32),availableH/(b.height+32)));return{x:side+(availableW-b.width*z)/2-b.x*z,y:top+(availableH-b.height*z)/2-b.y*z,z}}
// Only node coordinates change. Edge order, IDs, prompts and reference numbering stay intact.
export function arrangeTemplateGroups(graph,{overview=graph.nodes.length>16}={}){
 if(!graph.groups?.length)return graph;const groups=graph.groups.map(g=>({...g,collapsed:overview?true:!!g.collapsed})),positions=new Map();let x=40,y=110,rowHeight=0;const groupsPerRow=graph.nodes.length<=16&&groups.length<=3?3:2;
 groups.forEach((group,i)=>{if(i&&i%groupsPerRow===0){x=40;y+=rowHeight+92;rowHeight=0}const members=graph.nodes.filter(n=>group.nodeIds.includes(n.id)),columns=Math.min(4,Math.max(1,Math.ceil(Math.sqrt(members.length*1.2))));members.forEach((n,j)=>positions.set(n.id,{x:x+20+(j%columns)*(W+64),y:y+58+Math.floor(j/columns)*(H+76)}));const width=group.collapsed?324:Math.min(columns,members.length)*(W+64)-64+40,height=group.collapsed?150:Math.ceil(members.length/columns)*(H+76)-76+78;x+=width+100;rowHeight=Math.max(rowHeight,height)});
 return{...graph,groups,nodes:graph.nodes.map(n=>positions.has(n.id)?{...n,...positions.get(n.id)}:n)};
}
